.btn-primary:disabled { background: var(--border-strong); color: var(--text-disabled); box-shadow: none; cursor: not-allowed; }
.btn-primary.is-loading { color: transparent; position: relative; }

.btn-secondary { background: var(--color-secondary-500); color: var(--bg-base); }
.btn-secondary:hover { background: var(--color-secondary-700); }

.btn-ghost { background: transparent; color: var(--color-primary-600); border: 1.5px solid var(--border-strong); }
.btn-ghost:hover { background: var(--color-primary-50); border-color: var(--color-primary-500); }

.btn-danger { background: var(--color-error-fg); color: #1A0A03; }
.btn-danger:hover { filter: brightness(1.08); }
.input {
  font: 400 15px/1.4 'Pretendard', sans-serif;
