.card-outlined { box-shadow: none; border: 1.5px solid var(--border-default); }
.card-kraft { background: var(--bg-base); border: 1px dashed var(--border-strong); }  /* 크래프트지 질감 카드 */
.menu-card .photo { aspect-ratio: 4/3; border-radius: var(--radius-md); background: var(--bg-base); }
