.tag-veg     { background: var(--color-success-bg); color: var(--color-success-fg); }   /* 채식 재료 신호 */
.topnav { display: flex; align-items: center; gap: 24px; padding: 14px 48px; background: var(--color-neutral-0); color: var(--text-on-primary); }
.topnav .brand { color: var(--color-primary-500); font: 800 22px/1 'Gotham', Montserrat, sans-serif; letter-spacing: 0.06em; }
.topnav .link { font: 700 14px/1 'Gotham', Montserrat, sans-serif; color: var(--text-on-primary); text-decoration: none; opacity: 0.85; letter-spacing: 0.02em; }
.topnav .link:hover { opacity: 1; }
